mapper.select:
SELECT p.*, c.name AS owner_name, c.phone AS owner_phone FROM pet p JOIN customer c ON c.id = p.owner_id
AND (p.name LIKE '%' || #{keyword} || '%' OR c.name LIKE '%' || #{keyword} || '%' OR c.phone LIKE '%' || #{keyword} || '%')
ORDER BY p.id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE pet SET owner_id = #{ownerId}, name = #{name}, species = #{species}, breed = #{breed},
               gender = #{gender}, birthday = #{birthday}, weight_g = #{weightG},
               is_neutered = #{isNeutered}, color = #{color}, habit = #{habit}
WHERE id = #{id}
